L16:=ns*(1-(((((ns/n0)-1)/((ns/n0)*(astar/a)+1))*astar)/a)*exp(-(a+astar)*16
))/(1+(((ns/n0)-1)/((ns/n0)*(astar/a)+1))*exp(-(a+astar)*1));
"
result<-lavaan(model, data=modelData, fixed.x=FALSE, missing="FIML")
summary(result, fit.measures=TRUE)
